    $noindex=!installed() || ($data['preview']??false) || in_array($view,['404','privacy'],true);
    $schema=['@context'=>'https://schema.org','@type'=>'Organization','name'=>$s['brand'],'url'=>origin(),'logo'=>url('assets/arkesoft-logo-transparent.png')];
    if($s['email']) $schema['email']=$s['email']; if($s['phone']) $schema['telephone']=$s['phone'];
    if(in_array($view,['landing','service'],true)) {
        $schema=['@context'=>'https://schema.org','@type'=>'Service','name'=>$data['page']['heading']??$data['service']['name'],'description'=>$description,'url'=>$canonical,'provider'=>['@type'=>'Organization','name'=>$s['brand'],'url'=>origin()]];
