    }
?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?></title><meta name="description" content="<?=e($description)?>"><meta name="theme-color" content="#f5f5ed"><meta name="robots" content="<?=$noindex?'noindex, nofollow':'index, follow'?>"><link rel="canonical" href="<?=e($canonical)?>"><meta property="og:type" content="website"><meta property="og:locale" content="tr_TR"><meta property="og:title" content="<?=e($title)?>"><meta property="og:description" content="<?=e($description)?>"><meta property="og:url" content="<?=e($canonical)?>"><meta name="twitter:card" content="summary"><link rel="stylesheet" href="/assets/branding.css?v=2"><link rel="icon" href="/assets/arkesoft-logo-transparent.png" type="image/png"><link rel="stylesheet" href="/assets/site.css?v=1"><script defer src="/assets/site.js?v=1"></script><script type="application/ld+json"><?=json_encode($schema,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?></script></head>
